import { ConfigUrl, BROKEROS_HOST } from '../../../../../configs/url'

export const DYNAMIC_PURCHASE_FLOW_ACTIONS = {
  SET_CONTEXT_STATE: 'SET_CONTEXT_STATE',
  RESET_CONTEXT_STATE: 'RESET_CONTEXT_STATE',

  GET_PURCHASE_FLOW_CONFIG_REQUEST: 'GET_PURCHASE_FLOW_CONFIG_REQUEST',
  GET_PURCHASE_FLOW_CONFIG: 'GET_PURCHASE_FLOW_CONFIG',

  GET_PACKAGE_LIST_REQUEST: 'GET_PACKAGE_LIST_REQUEST',
  GET_PACKAGE_LIST: 'GET_PACKAGE_LIST',

  GET_PACKAGE_DETAIL_REQUEST: 'GET_PACKAGE_DETAIL_REQUEST',
  GET_PACKAGE_DETAIL: 'GET_PACKAGE_DETAIL',

  CREATE_POLICY_DRAFT_REQUEST: 'CREATE_POLICY_DRAFT_REQUEST',
  CREATE_POLICY_DRAFT: 'CREATE_POLICY_DRAFT',

  GET_POLICY_DRAFT_REQUEST: 'GET_POLICY_DRAFT_REQUEST',
  GET_POLICY_DRAFT: 'GET_POLICY_DRAFT',

  UPDATE_POLICY_DRAFT_REQUEST: 'UPDATE_POLICY_DRAFT_REQUEST',
  UPDATE_POLICY_DRAFT: 'UPDATE_POLICY_DRAFT',

  COMPLETE_POLICY_DRAFT_REQUEST: 'COMPLETE_POLICY_DRAFT_REQUEST',
  COMPLETE_POLICY_DRAFT: 'COMPLETE_POLICY_DRAFT',

  GET_POLICY_APPLICATION_DETAIL_REQUEST: 'GET_POLICY_APPLICATION_DETAIL_REQUEST',
  GET_POLICY_APPLICATION_DETAIL: 'GET_POLICY_APPLICATION_DETAIL',

  SHARE_QUOTATION_SLIP_REQUEST: 'SHARE_QUOTATION_SLIP_REQUEST',
  SHARE_QUOTATION_SLIP: 'SHARE_QUOTATION_SLIP',

  UPLOAD_BULK_EXCEL_REQUEST: 'UPLOAD_BULK_EXCEL_REQUEST',
  UPLOAD_BULK_EXCEL: 'UPLOAD_BULK_EXCEL',

  GET_POPUP_API_OPTIONS_REQUEST: 'GET_POPUP_API_OPTIONS_REQUEST',
  GET_POPUP_API_OPTIONS: 'GET_POPUP_API_OPTIONS',
}

export const setContextStateAction = (payload = {}) => ({
  type: DYNAMIC_PURCHASE_FLOW_ACTIONS.SET_CONTEXT_STATE,
  payload,
})

export const resetContextStateAction = (payload) => ({
  type: DYNAMIC_PURCHASE_FLOW_ACTIONS.RESET_CONTEXT_STATE,
  payload,
})

export const getPurchaseFlowConfigAction = ({ productCode }) => ({
  type: DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_PURCHASE_FLOW_CONFIG_REQUEST,
  payload: {
    method: 'GET',
    url: ConfigUrl.getPurchaseFlowConfigApi(productCode),
  },
})

export const getPackageListAction = ({ productCode, ...payload }) => ({
  type: DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_PACKAGE_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.getPackagesV2(),
  },
})

export const getPackageDetailAction = ({ packageCode, ...payload }) => ({
  type: DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_PACKAGE_DETAIL_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.getPackageDetailV2(),
  },
})

export const createPolicyDraftAction = (payload) => ({
  type: DYNAMIC_PURCHASE_FLOW_ACTIONS.CREATE_POLICY_DRAFT_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: ConfigUrl.createPolicyDraftApi,
  },
})

