export const shareQuotationSlipAction = (payload) => ({
  type: DYNAMIC_PURCHASE_FLOW_ACTIONS.SHARE_QUOTATION_SLIP,
  payload: {
    ...payload,
    url: ConfigUrl.shareDraftQuoteApiV2,
    method: 'POST',
  },
})

export const uploadBulkExcelAction = ({ draftId, uploadEndpoint, ...payload }) => {
  if (!uploadEndpoint) {
    throw new Error(
      'uploadEndpoint is missing please configure upload_url in control panel via purchase flow config'
    )
  }

  return {
    type: DYNAMIC_PURCHASE_FLOW_ACTIONS.UPLOAD_BULK_EXCEL_REQUEST,
    payload: {
      ...payload,
      method: 'POST',
      url: uploadEndpoint,
    },
  }
}

export const getPopupApiOptionsAction = ({ url = '', ...payload }) => ({
  type: DYNAMIC_PURCHASE_FLOW_ACTIONS.GET_POPUP_API_OPTIONS_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: `${BROKEROS_HOST}${url}`,
  },
})
