import { CardListWrapper } from './index.style'
import PackageDetailCard from './packageDetailCard'
import {
  useGetPackages,
  useGetTravelDetails,
  useUpdateTravelDraft
} from '../../../../state/hooks/useTravelState'
import { useCallback, useEffect, useMemo, useState } from 'react'
import Container from '../../../../../../../components/Container'
import {
  updateLoader,
  useErrorContextValue,
  useLoaderContextValue,
  useResetError
} from '@pasarpolis/common-react-hooks'
import { useHistory, useParams } from 'react-router'
import { get } from 'lodash'
import PolicyStepsHeader from '../../../../../../../components/PolicyStepsHeader'
import { TRAVEL_STEPS } from '../../../../constant'
import PackageNotFound from '../../../../../Packages/components/PackageNotFound'

const PackageList = () => {
  const { id } = useParams()
  const history = useHistory()
  const { resetError } = useResetError()
  const [{ getPackagesData = {} }, getPackagesRequest] = useGetPackages()
  const [
    { GET_PACKAGES_LOADER },
    dispatchLoader
  ] = useLoaderContextValue()
  const [
    { getTravelDetailsData = {} },
    getTravelDetailsRequest
  ] = useGetTravelDetails()
  const [, updateTravelDraftRequest] = useUpdateTravelDraft()
  const [{ updateTravelDraftStatus }] = useErrorContextValue()
  const [policyDetail, setPolicyDetail] = useState({})
  const [draftLoader, setDraftLoader] = useState(false)

  const getInitialPackages = useCallback(() => {
    if (Object.keys(getTravelDetailsData).length) {
      setPolicyDetail(getTravelDetailsData)
      const payload = {
        purchase_type: 'new-purchase',
        code: 'travel-protection',
        start_date: get(getTravelDetailsData.policy_details, 'start_date'),
        end_date: get(getTravelDetailsData.policy_details, 'end_date'),
        travel_type: get(getTravelDetailsData.policy_details, 'travel_type'),
        source: get(getTravelDetailsData.policy_details, 'source'),
        destination: get(getTravelDetailsData.policy_details, 'destination'),
        destination_data: get(getTravelDetailsData.policy_details, 'destination_data'),
        policy_type: get(getTravelDetailsData.policy_details, 'policy_type'),
        schengen_visa: get(getTravelDetailsData.policy_details, 'schengen_visa'),
        additional_member_count: get(
          getTravelDetailsData.policy_details,
          'additional_member_count'
        )
      }
      getPackagesRequest({
        body: {
          ...payload
        }
      })
    }
  }, [getPackagesRequest, getTravelDetailsData])

  useEffect(() => {
    if (id) {
      getTravelDetailsRequest({ draftQuoteId: id })
    }
  }, [getTravelDetailsRequest, id])

  const isPkgsEmpty = useMemo(() => {
    if (getPackagesData['error-code']) {
      return true
    }
    return !getPackagesData?.complete_match?.length
  }, [getPackagesData])

  useEffect(() => {
    return () => {
      dispatchLoader(
        updateLoader({
          GET_PACKAGES_LOADER: undefined
        })
      )
    }
  }, [dispatchLoader])

  useEffect(() => {
    getInitialPackages()
  }, [getInitialPackages])

  useEffect(() => {
    resetError(['updateTravelDraftStatus'])
    if (updateTravelDraftStatus === 'success') {
      setDraftLoader(false)
      history.push({
        pathname: `/travel/package_detail/${id}`,
        state: {
          activeTab: 0
        }
      })
    }
  }, [updateTravelDraftStatus, resetError])

  const handleBackClick = () => {
    history.push({
      pathname: `/travel/${id}`
    })
  }

  const handlePackageClick = (code) => {
    setDraftLoader(true)
    updateTravelDraftRequest({
      body: {
        section: 'package_insurance',
        sub_section: 'package_list',
        data: {
          ...policyDetail.policy_details,
          package_code: code
        }
      },
      draftQuoteId: id
    })
  }

  return (
    <Container
      title='Daftar Paket'
      onClose={() => history.replace('/dashboard')}
      showCloseIcon
      displayBackButton
      hideBottomTabs
      loader={
        GET_PACKAGES_LOADER || draftLoader
      }
      onBackClick={handleBackClick}
    >
      <PolicyStepsHeader
        stepsData={TRAVEL_STEPS}
        activeCount={2}
        prevActive={{
          1: true
        }}
      />
      {(GET_PACKAGES_LOADER === false) && !isPkgsEmpty && (
        <>
          {
            !!(getPackagesData?.complete_match.length > 0) && (
              <CardListWrapper>
                {getPackagesData?.complete_match?.map((pack) => {
                  return (
                    <PackageDetailCard
                      props={pack}
                      handlePackageClick={handlePackageClick}
                    />
                  )
                })}
              </CardListWrapper>
            )
          }
        </>
      )}
      {
        (GET_PACKAGES_LOADER === false) && isPkgsEmpty && (
          <PackageNotFound history={history} showProductBtn={false} />
        )
      }
    </Container>
  )
}

export default PackageList
