import { useCallback } from 'react'
import { useHistory } from 'react-router'
import { ARROW_RIGHT_WHITE } from '../../../../images'
import { StyleContainer } from './index.style'

const ACTION_TYPE = {
  LINK: 'LINK',
  FORM_UPDATE: 'FORM_UPDATE',
}

function ActionBox({
  type,
  title,
  content,
  actionType,
  actionLinkUrl,
  actionFormUpdateData,
  onChange,
}) {
  const history = useHistory()
  const isClickable = actionType === 'LINK' || actionType === 'FORM_UPDATE'

  const handleClick = useCallback(() => {
    switch (actionType) {
      case ACTION_TYPE.LINK:
        return history.push(actionLinkUrl)
      case ACTION_TYPE.FORM_UPDATE:
        try {
          const parsedData = JSON.parse(actionFormUpdateData)
          return onChange({}, parsedData)
        } catch (err) {
          console.error(err)
          return
        }
      default:
        return
    }
  }, [history, actionType, actionLinkUrl, actionFormUpdateData, onChange])

  const handleKeyDown = useCallback(
    (e) => {
      if (!isClickable) return
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault()
        handleClick()
      }
    },
    [handleClick, isClickable]
  )

  return (
    <StyleContainer
      type={type}
      tabIndex={0}
      role="button"
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      data-testid="action-box"
    >
      <div>
        {title && (
          <div className="action-box__title" data-testid="action-box-title">
            {title}
          </div>
        )}
        <div
          className="action-box__content"
          data-testid="action-box-content"
          dangerouslySetInnerHTML={{ __html: content || '' }}
        />
      </div>
      <img src={ARROW_RIGHT_WHITE} alt="Next" />
    </StyleContainer>
  )
}

export default ActionBox
