import { useState } from 'react'
import { MV_RENEWAL_FLOW } from '../../../constants/pkgCode'
import useEventTracker from '../../../hooks/trackers'
import useRenewalAllocation from '../../../containers/Private/Policy/pages/RenewalList/hooks/useRenewalAllocation'
import ChasisNumberInput from '../components/ChasisNumberInput'
import FoundVehicleDetails from '../components/FoundVehicleDetails'
import DocumentUpload from '../components/DocumentUpload'
import EndorsementForm from '../components/EndorsementForm'
import EndorsementSuccess from '../components/EndorsementSuccess'

const CONTENT = {
  CHASIS_NUMBER_INPUT: 'CHASIS_NUMBER_INPUT',
  DOCUMENT_UPLOAD: 'DOCUMENT_UPLOAD',
  FOUND_VEHICLE_DETAILS: 'FOUND_VEHICLE_DETAILS',
  ENDORSEMENT_FORM: 'ENDORSEMENT_FORM',
  ENDORSEMENT_SUCCESS: 'ENDORSEMENT_SUCCESS',
}

function MVChasisNumberCheckModal({ renewalFlow, onClose, onBeginNewPurchase, onBeginRenewal }) {
  const [showContent, setShowContent] = useState(CONTENT.CHASIS_NUMBER_INPUT)
  const [vehicleData, setVehicleData] = useState(null)
  const [dataSource, setDataSource] = useState(null)

  const { redirectToRenewalAllocation } = useRenewalAllocation()
  const { trackUserEvent } = useEventTracker()

  const handleBeginRenewal = () => {
    trackUserEvent('[MV Renewal] Renew Policy', {
      source:
        dataSource === CONTENT.CHASIS_NUMBER_INPUT
          ? 'Policy Chasis Number'
          : dataSource === CONTENT.DOCUMENT_UPLOAD
            ? 'Upload SCP'
            : null,
      channel: renewalFlow === MV_RENEWAL_FLOW.O2O ? 'O2O' : 'online',
      insurance_provider: null,
      vehicle_brand: vehicleData?.brand_data?.name,
      vehicle_model: vehicleData?.model_data?.model_name,
      vehicle_year: vehicleData?.year,
      original_application_no: null,
    })
    if (vehicleData?.renewal_one_tap_eligibility) {
      redirectToRenewalAllocation({
        referenceId: vehicleData?.reference_id,
        allocation: vehicleData?.renewal_allocation,
      })
      return
    }
    onBeginRenewal(vehicleData)
  }

  return (
    <>
      {showContent === CONTENT.CHASIS_NUMBER_INPUT && (
        <ChasisNumberInput
          show={showContent === CONTENT.CHASIS_NUMBER_INPUT}
          renewalFlow={renewalFlow}
          onClose={onClose}
          onSearchSuccess={(data) => {
            setShowContent(CONTENT.FOUND_VEHICLE_DETAILS)
            setVehicleData(data)
            setDataSource(CONTENT.CHASIS_NUMBER_INPUT)
          }}
          onClickUploadDocument={() => setShowContent(CONTENT.DOCUMENT_UPLOAD)}
          onClickSkip={() => onBeginNewPurchase()}
        />
      )}
      {showContent === CONTENT.DOCUMENT_UPLOAD && (
        <DocumentUpload
          show={showContent === CONTENT.DOCUMENT_UPLOAD}
          onClose={onClose}
          onClickSkip={() => onBeginNewPurchase()}
          onClickBack={() => setShowContent(CONTENT.CHASIS_NUMBER_INPUT)}
          onVehicleDataNotFound={(data) => onBeginNewPurchase(data)}
          onVehicleDataFound={(data) => {
            setShowContent(CONTENT.FOUND_VEHICLE_DETAILS)
            setVehicleData(data)
            setDataSource(CONTENT.DOCUMENT_UPLOAD)
          }}
        />
      )}
      {showContent === CONTENT.FOUND_VEHICLE_DETAILS && (
        <FoundVehicleDetails
          show={showContent === CONTENT.FOUND_VEHICLE_DETAILS}
          vehicleData={vehicleData}
          onClose={onClose}
          onClickBack={() => {
            setShowContent(CONTENT.CHASIS_NUMBER_INPUT)
            setVehicleData(null)
            setDataSource(null)
          }}
          onClickBegin={handleBeginRenewal}
          onClickEndorsement={() => setShowContent(CONTENT.ENDORSEMENT_FORM)}
        />
      )}
      {showContent === CONTENT.ENDORSEMENT_FORM && (
        <EndorsementForm
          show={showContent === CONTENT.ENDORSEMENT_FORM}
          vehicleData={vehicleData}
          onClose={onClose}
          onClickBack={() => {
            setShowContent(CONTENT.CHASIS_NUMBER_INPUT)
            setVehicleData(null)
            setDataSource(null)
          }}
          onEndorsementSuccess={() => setShowContent(CONTENT.ENDORSEMENT_SUCCESS)}
        />
      )}
      {showContent === CONTENT.ENDORSEMENT_SUCCESS && (
        <EndorsementSuccess show={showContent === CONTENT.ENDORSEMENT_SUCCESS} onClose={onClose} />
      )}
    </>
  )
}

export default MVChasisNumberCheckModal
