import { ConfigUrl } from '../../../configs/url'

export const ADDRESS_ACTIONS = {
  GET_PROVINCE_LIST_REQUEST: 'GET_PROVINCE_LIST_REQUEST',
  GET_PROVINCE_LIST: 'GET_PROVINCE_LIST',

  GET_CITY_LIST_REQUEST: 'GET_CITY_LIST_REQUEST',
  GET_CITY_LIST: 'GET_CITY_LIST',

  VALIDATE_POSTAL_CODE_REQUEST: 'VALIDATE_POSTAL_CODE_REQUEST',
  VALIDATE_POSTAL_CODE: 'VALIDATE_POSTAL_CODE'
}

export const getProvinceList = (payload) => ({
  type: ADDRESS_ACTIONS.GET_PROVINCE_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'get',
    url: ConfigUrl.getPropertyProvinceApi
  }
})

export const getCityList = (payload) => ({
  type: ADDRESS_ACTIONS.GET_CITY_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'get',
    url: ConfigUrl.getPropertyCities(payload.province)
  }
})

// body: {
//   postal_code: '12345'
// }
export const validatePostalCode = (payload) => ({
  type: ADDRESS_ACTIONS.VALIDATE_POSTAL_CODE_REQUEST,
  payload: {
    ...payload,
    method: 'post',
    url: ConfigUrl.validatePostalCodeApi
  }
})
