import { useParams } from "react-router";
import { useHistory } from 'react-router-dom'
import {
  CardWrapper,
  CardHeaderCtn,
  CardHeading2,
  CardHeading,
  CardDetailsCtn,
  PriceDetails,
  CardDetailsHeaderCtn,
  ImageCtn,
  CardCtn
} from "./index.style";
import { useCallback, useMemo } from "react";
import { formatMoney } from "../../../../../../../helpers/utility";
import { get } from "lodash";

const PackageDetailCard = ({ props, policyData = {}, handlePackageClick = () => {} }) => {

  const packageData = useMemo(() => {
    return {
        providerName: get(props, 'provider.name', ''),
        packageName: get(props, 'package.name', ''),
        premiumAmount: get(props, 'premium.amount', 0),
        premiumAmount2: get(props, 'basic_premium', 0),
        cancellationBenifit: get(props, 'cancellation_benifit', ''),
        medicalBenifit: get(props, 'medical_benifit', ''),
        medicalBenefitAbove65: get(props, 'medical_benefit_above_65', ''),
        lostBaggageBenifit: get(props, 'lost_baggage_benifit', ''),
        commissionPercent: get(props, 'commission_rate', 0),
        commissionAmount: get(props, 'commission', 0),
    }
  }, [props])

  const renderCardDetails = useCallback((text, amount) => {
    return (
      <CardDetailsCtn>
        <PriceDetails>{text}</PriceDetails>
        <PriceDetails>{amount}</PriceDetails>
      </CardDetailsCtn>
    );
  }, []);

  const renderHeadingDetails = useCallback((text, amount, textAlign) => {
    return (
      <CardCtn textAlign={textAlign}>
        <CardHeading>{text}</CardHeading>
        <CardHeading2>{amount}</CardHeading2>
      </CardCtn>
    );
  }, []);

  return (
    <CardWrapper onClick={() => handlePackageClick(props.code)}>
      <CardHeaderCtn>
        <ImageCtn>
          {props?.package?.product?.logo && <img
            src={props?.package?.product?.logo}
            width={24}
            height={24}
            alt="logo"
            lassName="logo-image"
          />}
        </ImageCtn>
        <CardHeading textAlign="center">{packageData.providerName}</CardHeading>
        <CardHeading2 textAlign="center">{packageData.packageName}</CardHeading2>
      </CardHeaderCtn>
      <CardDetailsHeaderCtn>
        {renderHeadingDetails("PREMI DASAR", formatMoney((packageData.premiumAmount || packageData.premiumAmount2), 0, 'IDR'), "left")}
        {renderHeadingDetails(
          `KOMISI ${packageData.commissionPercent}%`,
          formatMoney(packageData.commissionAmount, 0, 'IDR'),
          'right'
        )}
      </CardDetailsHeaderCtn>
      {renderCardDetails(
        "Pembatalan Perjalanan",
        formatMoney(packageData.cancellationBenifit, 0, 'IDR')
      )}
      {renderCardDetails(
        "Biaya Medis (Usia ≤ 65 thn)",
        formatMoney(packageData.medicalBenifit, 0, 'IDR')
      )}
      {renderCardDetails(
        "Biaya Medis (Usia 66-84)",
        formatMoney(packageData.medicalBenefitAbove65, 0, 'IDR')
      )}
      {renderCardDetails(
        "Kehilangan Bagasi",
        formatMoney(packageData.lostBaggageBenifit, 0, 'IDR')
      )}
    </CardWrapper>
  );
};

export default PackageDetailCard;
